class Solution {
public:
 int longestPalindrome(string word1,string word2){
  string s=word1+word2;int n=s.size(),split=word1.size();
  vector<vector<int>> dp(n,vector<int>(n));
  for(int i=n-1;i>=0;--i){dp[i][i]=1;
   for(int j=i+1;j<n;++j){
    if(s[i]==s[j])dp[i][j]=2+(i+1<=j-1?dp[i+1][j-1]:0);
    else dp[i][j]=max(dp[i+1][j],dp[i][j-1]);
   }
  }
  int ans=0;
  for(int i=0;i<split;++i)for(int j=split;j<n;++j)if(s[i]==s[j])
   ans=max(ans,2+(i+1<=j-1?dp[i+1][j-1]:0));
  return ans;
 }
};
